      return false;
    }
    if (identical(this, other)) {
      return true;
    }
    return _deepEquals(sdkInt, other.sdkInt) && _deepEquals(tier, other.tier) && _deepEquals(osTrashBin, other.osTrashBin) && _deepEquals(allFilesAccessPossible, other.allFilesAccessPossible) && _deepEquals(allFilesAccessGranted, other.allFilesAccessGranted) && _deepEquals(legacyStorageGranted, other.legacyStorageGranted) && _deepEquals(appDataReadable, other.appDataReadable) && _deepEquals(mediaStoreOnly, other.mediaStoreOnly);
  }

  @override
