class _PigeonCodec extends StandardMessageCodec {
  const _PigeonCodec();
  @override
  void writeValue(WriteBuffer buffer, Object? value) {
    if (value is int) {
      buffer.putUint8(4);
      buffer.putInt64(value);
    }    else if (value is ProbeCapabilities) {
      buffer.putUint8(129);
      writeValue(buffer, value.encode());
    }    else if (value is CpuCluster) {
      buffer.putUint8(130);
      writeValue(buffer, value.encode());
    }    else if (value is CpuInfo) {
      buffer.putUint8(131);
      writeValue(buffer, value.encode());
    }    else if (value is CpuSample) {
      buffer.putUint8(132);
      writeValue(buffer, value.encode());
    }    else if (value is ThermalZone) {
      buffer.putUint8(133);
      writeValue(buffer, value.encode());
    }    else if (value is ThermalSample) {
      buffer.putUint8(134);
      writeValue(buffer, value.encode());
    }    else if (value is BatterySnapshot) {
      buffer.putUint8(135);
      writeValue(buffer, value.encode());
    }    else if (value is MemorySnapshot) {
      buffer.putUint8(136);
      writeValue(buffer, value.encode());
    }    else if (value is SensorInfo) {
      buffer.putUint8(137);
      writeValue(buffer, value.encode());
    }    else if (value is DeviceSnapshot) {
      buffer.putUint8(138);
      writeValue(buffer, value.encode());
    }    else if (value is StorageAccess) {
      buffer.putUint8(139);
      writeValue(buffer, value.encode());
    }    else if (value is DeviceIdentity) {
      buffer.putUint8(140);
      writeValue(buffer, value.encode());
    } else {
      super.writeValue(buffer, value);
    }
  }

  @override
  Object? readValueOfType(int type, ReadBuffer buffer) {
    switch (type) {
      case 129:
        return ProbeCapabilities.decode(readValue(buffer)!);
      case 130:
        return CpuCluster.decode(readValue(buffer)!);
      case 131:
        return CpuInfo.decode(readValue(buffer)!);
      case 132:
        return CpuSample.decode(readValue(buffer)!);
      case 133:
        return ThermalZone.decode(readValue(buffer)!);
      case 134:
        return ThermalSample.decode(readValue(buffer)!);
      case 135:
        return BatterySnapshot.decode(readValue(buffer)!);
      case 136:
        return MemorySnapshot.decode(readValue(buffer)!);
      case 137:
        return SensorInfo.decode(readValue(buffer)!);
      case 138:
        return DeviceSnapshot.decode(readValue(buffer)!);
      case 139:
        return StorageAccess.decode(readValue(buffer)!);
      case 140:
        return DeviceIdentity.decode(readValue(buffer)!);
      default:
        return super.readValueOfType(type, buffer);
    }
  }
}

